/* machine-generated by m2c: a starting point, not a match */

extern s16 gGameModeTable;
extern s32 gGameMode;
extern u16 gSightRangeIndex;

/* Sets the game mode and stores its index in the 32-entry mode table (0 if absent). */ void setGameModeAndLookupIndex(s32 mode) {
    char *entry;
    s32 i;

    i = 0;
    entry = &gGameModeTable;
    gGameMode = mode;
    gSightRangeIndex = 0;
    do {
        if (*(s16 *)entry == mode) {
            gSightRangeIndex = i;
            return;
        }
        i += 1;
        entry += 2;
    } while (i < 0x20U);
}
